CREATE TABLE game_assets (
  id text PRIMARY KEY, game_id text NOT NULL REFERENCES games(id), label text NOT NULL,
  visibility text NOT NULL CHECK (visibility IN ('public','spoiler')),
  alt_text text NOT NULL CHECK (length(alt_text) BETWEEN 1 AND 500),
  source_workflow text, source_run_id text, object_key text NOT NULL UNIQUE, sha256 text NOT NULL,
  width integer NOT NULL CHECK (width BETWEEN 1 AND 4096), height integer NOT NULL CHECK (height BETWEEN 1 AND 4096),
  byte_length integer NOT NULL CHECK (byte_length BETWEEN 1 AND 10485760), revision integer NOT NULL DEFAULT 1 CHECK (revision > 0),
  created_by_id text NOT NULL REFERENCES users(id), updated_by_id text NOT NULL REFERENCES users(id),
  created_at text NOT NULL, updated_at text NOT NULL, deleted_at text,
  CHECK (label ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND length(label) <= 64)
);
CREATE INDEX game_assets_list_idx ON game_assets(game_id,id);
CREATE UNIQUE INDEX game_assets_live_banner_unique ON game_assets(game_id) WHERE label = 'banner' AND deleted_at IS NULL;
CREATE TABLE game_asset_operations (
  id text PRIMARY KEY, actor_id text NOT NULL REFERENCES users(id), request_id text NOT NULL CHECK (length(request_id) BETWEEN 1 AND 200),
  game_id text NOT NULL REFERENCES games(id), asset_id text NOT NULL, kind text NOT NULL CHECK (kind IN ('upload','update','replace','delete')),
  fingerprint text NOT NULL, state text NOT NULL CHECK (state IN ('pending','applied','failed','cancelled')),
  claim_id text NOT NULL, claim_until text NOT NULL, candidate_key text, retired_key text,
  cleanup_pending boolean NOT NULL DEFAULT false, result jsonb, created_at text NOT NULL, updated_at text NOT NULL
);
CREATE UNIQUE INDEX game_asset_operations_request_unique ON game_asset_operations(actor_id,request_id);
CREATE INDEX game_asset_operations_game_idx ON game_asset_operations(game_id);
